<?php $rows=db()->query('SELECT id,name,email,role,active,created_at FROM users ORDER BY created_at DESC')->fetchAll(); ?>
<section class="card panel"><div class="panel-head"><h2>Crear cuenta de personal</h2></div><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="user_create"><label>Nombre completo<input name="name" required></label><label>Correo electrónico<input name="email" type="email" required></label><label>Contraseña temporal<input name="password" type="password" minlength="10" required></label><label>Rol<select name="role"><option value="recepcionista">Recepcionista</option><option value="admin">Administrador</option></select></label><div class="form-actions"><button class="btn primary">Crear usuario</button></div></form></section><section class="card panel"><div class="panel-head"><h2>Usuarios del sistema</h2></div><table><thead><tr><th>NOMBRE</th><th>CORREO</th><th>ROL</th><th>ESTADO</th><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=h($r['name'])?></td><td><?=h($r['email'])?></td><td><?=h(ucfirst($r['role']))?></td><td><span class="pill <?=$r['active']?'':'inactive'?>"><?=$r['active']?'Activo':'Inactivo'?></span></td><td><?php if((int)$r['id']!==(int)current_user()['id']): ?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="user_toggle"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="link-btn"><?=$r['active']?'Desactivar':'Activar'?></button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></section>
